import unittest

from timestamps import format_timestamp


class FormatTimestampTests(unittest.TestCase):
    def test_formats_analytics_as_utc_without_suffix(self):
        self.assertEqual(
            format_timestamp("2024-01-02T03:04:05+08:00", "analytics"),
            "2024-01-01 19:04:05",
        )

    def test_formats_public_api_as_utc_rfc3339(self):
        self.assertEqual(
            format_timestamp("2024-01-02T03:04:05-05:00", "public_api"),
            "2024-01-02T08:04:05Z",
        )

    def test_accepts_z_and_discards_fractional_seconds(self):
        self.assertEqual(
            format_timestamp("2024-01-02T03:04:05.999999Z", "public_api"),
            "2024-01-02T03:04:05Z",
        )

    def test_rejects_unknown_target(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-02T03:04:05Z", "other")

    def test_rejects_timestamp_without_timezone(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-02T03:04:05", "analytics")


if __name__ == "__main__":
    unittest.main()

