from datetime import datetime, timezone


_ANALYTICS_FORMAT = "%Y-%m-%d %H:%M:%S"


def format_timestamp(iso_timestamp, target):
    """Format an aware ISO 8601 timestamp for a supported consumer.

    Analytics uses a UTC timestamp without a timezone suffix, while the public
    API uses a UTC RFC 3339 timestamp.  Both formats intentionally omit
    fractional seconds.
    """
    if target not in ("analytics", "public_api"):
        raise ValueError(f"unknown timestamp target: {target!r}")

    if not isinstance(iso_timestamp, str):
        raise TypeError("iso_timestamp must be an ISO 8601 string")

    # ``fromisoformat`` supports offsets but, on supported Python versions,
    # accepting ``Z`` explicitly keeps the input contract easy to see.
    timestamp = iso_timestamp[:-1] + "+00:00" if iso_timestamp.endswith("Z") else iso_timestamp
    parsed = datetime.fromisoformat(timestamp)
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("iso_timestamp must include a timezone")

    utc_timestamp = parsed.astimezone(timezone.utc)
    if target == "analytics":
        return utc_timestamp.strftime(_ANALYTICS_FORMAT)
    return utc_timestamp.strftime("%Y-%m-%dT%H:%M:%SZ")
